import { BrowserProvider, Contract } from "ethers";
// Generated by `npm run deploy:local` / `npm run deploy:sepolia` (scripts/deploy.js)
import deployment from "../contracts/UrbanIssueRegistry.json";

export const STATUSES = ["Reported", "Assigned", "InProgress", "Resolved", "Closed"];
export const PRIORITIES = ["Low", "Medium", "High", "Critical"];
export const ISSUE_TYPES = ["StreetLight", "Pothole", "Garbage", "WaterLeak", "Other"];
export const TARGET_CHAIN_ID = deployment.chainId;
export const CONTRACT_ADDRESS = deployment.address;
export const NETWORK_NAME = deployment.network;

// ---------- Wallet ----------
export async function connectWallet() {
  if (!window.ethereum) throw new Error("MetaMask not detected. Please install the extension.");
  const provider = new BrowserProvider(window.ethereum);
  await provider.send("eth_requestAccounts", []);
  const signer = await provider.getSigner();
  const network = await provider.getNetwork();
  const contract = new Contract(deployment.address, deployment.abi, signer);
  return { contract, account: await signer.getAddress(), chainId: Number(network.chainId) };
}

export async function switchToTargetChain() {
  const chainId = "0x" + TARGET_CHAIN_ID.toString(16);
  try {
    await window.ethereum.request({ method: "wallet_switchEthereumChain", params: [{ chainId }] });
  } catch (e) {
    if (e.code === 4902 && TARGET_CHAIN_ID === 31337) {
      await window.ethereum.request({
        method: "wallet_addEthereumChain",
        params: [{
          chainId,
          chainName: "Hardhat Local",
          rpcUrls: ["http://127.0.0.1:8545"],
          nativeCurrency: { name: "ETH", symbol: "ETH", decimals: 18 },
        }],
      });
    } else {
      throw e;
    }
  }
}

// ---------- Reads ----------
const toIssue = (r) => ({
  issueId: r.issueId,
  issueType: r.issueType,
  location: r.location,
  description: r.description,
  reportDate: r.reportDate,
  priority: Number(r.priority),
  reportedBy: r.reportedBy,
  reporter: r.reporter,
  assignedTo: r.assignedTo,
  status: Number(r.status),
  createdAt: Number(r.createdAt),
  updatedAt: Number(r.updatedAt),
});

export async function loadIssues(contract) {
  const ids = await contract.getAllIssueIds();
  const list = await Promise.all(ids.map((id) => contract.getIssue(id)));
  return list.map(toIssue);
}

export async function loadHistory(contract, issueId) {
  const entries = await contract.getHistory(issueId);
  return entries.map((h) => ({
    status: Number(h.status),
    assignedTo: h.assignedTo,
    changedBy: h.changedBy,
    timestamp: Number(h.timestamp),
    note: h.note,
  }));
}

export async function loadRole(contract, account) {
  const owner = await contract.owner();
  const isOwner = owner.toLowerCase() === account.toLowerCase();
  const isStaff = isOwner || (await contract.operators(account));
  return { isOwner, isStaff };
}

// ---------- Errors ----------
export function parseError(e) {
  if (e?.code === "ACTION_REJECTED" || e?.code === 4001) return "Transaction rejected in MetaMask.";
  if (e?.code === "INSUFFICIENT_FUNDS") return "Insufficient funds to pay the gas fee.";
  const msg = e?.reason || e?.revert?.args?.[0] || e?.shortMessage || e?.message || "Unknown error";
  return String(msg).replace(/^execution reverted: /, "");
}
